window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7dcce12c22a6e03b"]={"versions": [{"id": "FIG-7dcce12c22a6e03b", "releases": ["R4.1.3", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) aus der Spezifikation des AUTOSAR Classic Platform Basissoftware-Moduls COM (AUTOSAR_SWS_COM, Kapitel 7.3.3.2). Das Diagramm veranschaulicht das Sendezeitverhalten eines I-PDUs im periodischen Übertragungsmodus (Transmission Mode PERIODIC) ohne Umschaltung des Transmission Mode Selectors (TMS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t)</strong>: Horizontale Achse zur Darstellung des zeitlichen Fortschritts.\n</li><li><strong>Sendeereignisse (grüne Pfeile nach unten)</strong>: Regelmäßige Übertragungszeitpunkte eines I-PDUs auf den Kommunikationsbus.\n</li><li><strong>Periodendauer (t_c)</strong>: Zeitintervall bzw. Zykluszeit zwischen zwei aufeinanderfolgenden periodischen Sendeaufrufen (<code>ComTxModeTimePeriod</code>).\n</li><li><strong>Software-/Signal-Aktualisierungen (rote Dreiecke mit Beschriftung v=x)</strong>: Schreiboperationen der oberen Schicht (z. B. RTE / SWC via <code>Com_SendSignal</code>) mit neuen Signalwerten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Übertragung erfolgt strikt periodisch in äquidistanten Intervallen der Dauer t_c, getaktet durch das COM-Hauptzeitraster bzw. den periodischen Timer.\n</li><li>Ankommende Signalaktualisierungen (v=x, dargestellt durch rote Dreiecke) treffen asynchron zur Sendeperiode ein (hier zwei Ereignisse innerhalb des zweiten Zyklus und eines im dritten Zyklus).\n</li><li>Da der Übertragungsmodus rein periodisch (<code>PERIODIC</code>) konfiguriert ist und kein TMS-Moduswechsel ausgelöst wird, triggern die Schreiboperationen keine unmittelbare oder zusätzliche Übertragung.\n</li><li>Die aktualisierten Daten werden im I-PDU-Puffer zwischengespeichert und beim planmäßigen Ablauf der Zykluszeit t_c mit der nächsten regulären periodischen Sendung übertragen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht das Standardverhalten für I-PDUs mit <code>ComTxModeMode = PERIODIC</code>.\n</li><li>Für Systementwickler und BSW-Konfiguratoren verdeutlicht das Diagramm, dass im reinen periodischen Modus keine ereignisgesteuerte Sendeauslösung stattfindet; die Signalaktualisierungen werden ausschließlich im Takt von <code>ComTxModeTimePeriod</code> (t_c) übermittelt.\n</li><li>Eine Entprellung über <code>ComTxModeTimeOffset</code> oder Mindestabstandsüberwachung (<code>ComTxModeRepetitionPeriod</code> / <code>ComMinimumDelayTime</code>) ist in diesem ungestörten stationären Zustand nicht aktiv bzw. nicht wirksam.\n</li></ul>"}, {"id": "FIG-d1b84f0070e4dbff", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) aus der Spezifikation des AUTOSAR Classic Platform Basissoftware-Moduls COM (AUTOSAR_SWS_COM, Kapitel 7.3.3.2). Das Diagramm veranschaulicht das Sendezeitverhalten eines I-PDUs im periodischen Übertragungsmodus (Transmission Mode PERIODIC) ohne Umschaltung des Transmission Mode Selectors (TMS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t)</strong>: Horizontale Achse zur Darstellung des zeitlichen Fortschritts.\n</li><li><strong>Sendeereignisse (grüne Pfeile nach unten)</strong>: Regelmäßige Übertragungszeitpunkte eines I-PDUs auf den Kommunikationsbus.\n</li><li><strong>Periodendauer (t_c)</strong>: Zeitintervall bzw. Zykluszeit zwischen zwei aufeinanderfolgenden periodischen Sendeaufrufen (<code>ComTxModeTimePeriod</code>).\n</li><li><strong>Software-/Signal-Aktualisierungen (rote Dreiecke mit Beschriftung v=x)</strong>: Schreiboperationen der oberen Schicht (z. B. RTE / SWC via <code>Com_SendSignal</code>) mit neuen Signalwerten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Übertragung erfolgt strikt periodisch in äquidistanten Intervallen der Dauer t_c, getaktet durch das COM-Hauptzeitraster bzw. den periodischen Timer.\n</li><li>Ankommende Signalaktualisierungen (v=x, dargestellt durch rote Dreiecke) treffen asynchron zur Sendeperiode ein (hier zwei Ereignisse innerhalb des zweiten Zyklus und eines im dritten Zyklus).\n</li><li>Da der Übertragungsmodus rein periodisch (<code>PERIODIC</code>) konfiguriert ist und kein TMS-Moduswechsel ausgelöst wird, triggern die Schreiboperationen keine unmittelbare oder zusätzliche Übertragung.\n</li><li>Die aktualisierten Daten werden im I-PDU-Puffer zwischengespeichert und beim planmäßigen Ablauf der Zykluszeit t_c mit der nächsten regulären periodischen Sendung übertragen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht das Standardverhalten für I-PDUs mit <code>ComTxModeMode = PERIODIC</code>.\n</li><li>Für Systementwickler und BSW-Konfiguratoren verdeutlicht das Diagramm, dass im reinen periodischen Modus keine ereignisgesteuerte Sendeauslösung stattfindet; die Signalaktualisierungen werden ausschließlich im Takt von <code>ComTxModeTimePeriod</code> (t_c) übermittelt.\n</li><li>Eine Entprellung über <code>ComTxModeTimeOffset</code> oder Mindestabstandsüberwachung (<code>ComTxModeRepetitionPeriod</code> / <code>ComMinimumDelayTime</code>) ist in diesem ungestörten stationären Zustand nicht aktiv bzw. nicht wirksam.\n</li></ul>"}, {"id": "FIG-3bdec3d0fa4ae14f", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) aus der Spezifikation des AUTOSAR Classic Platform Basissoftware-Moduls COM (AUTOSAR_SWS_COM, Kapitel 7.3.3.2). Das Diagramm veranschaulicht das Sendezeitverhalten eines I-PDUs im periodischen Übertragungsmodus (Transmission Mode PERIODIC) ohne Umschaltung des Transmission Mode Selectors (TMS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t)</strong>: Horizontale Achse zur Darstellung des zeitlichen Fortschritts.\n</li><li><strong>Sendeereignisse (grüne Pfeile nach unten)</strong>: Regelmäßige Übertragungszeitpunkte eines I-PDUs auf den Kommunikationsbus.\n</li><li><strong>Periodendauer (t_c)</strong>: Zeitintervall bzw. Zykluszeit zwischen zwei aufeinanderfolgenden periodischen Sendeaufrufen (<code>ComTxModeTimePeriod</code>).\n</li><li><strong>Software-/Signal-Aktualisierungen (rote Dreiecke mit Beschriftung v=x)</strong>: Schreiboperationen der oberen Schicht (z. B. RTE / SWC via <code>Com_SendSignal</code>) mit neuen Signalwerten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Übertragung erfolgt strikt periodisch in äquidistanten Intervallen der Dauer t_c, getaktet durch das COM-Hauptzeitraster bzw. den periodischen Timer.\n</li><li>Ankommende Signalaktualisierungen (v=x, dargestellt durch rote Dreiecke) treffen asynchron zur Sendeperiode ein (hier zwei Ereignisse innerhalb des zweiten Zyklus und eines im dritten Zyklus).\n</li><li>Da der Übertragungsmodus rein periodisch (<code>PERIODIC</code>) konfiguriert ist und kein TMS-Moduswechsel ausgelöst wird, triggern die Schreiboperationen keine unmittelbare oder zusätzliche Übertragung.\n</li><li>Die aktualisierten Daten werden im I-PDU-Puffer zwischengespeichert und beim planmäßigen Ablauf der Zykluszeit t_c mit der nächsten regulären periodischen Sendung übertragen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht das Standardverhalten für I-PDUs mit <code>ComTxModeMode = PERIODIC</code>.\n</li><li>Für Systementwickler und BSW-Konfiguratoren verdeutlicht das Diagramm, dass im reinen periodischen Modus keine ereignisgesteuerte Sendeauslösung stattfindet; die Signalaktualisierungen werden ausschließlich im Takt von <code>ComTxModeTimePeriod</code> (t_c) übermittelt.\n</li><li>Eine Entprellung über <code>ComTxModeTimeOffset</code> oder Mindestabstandsüberwachung (<code>ComTxModeRepetitionPeriod</code> / <code>ComMinimumDelayTime</code>) ist in diesem ungestörten stationären Zustand nicht aktiv bzw. nicht wirksam.\n</li></ul>"}], "trans": [{"from": "FIG-7dcce12c22a6e03b", "to": "FIG-d1b84f0070e4dbff", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d1b84f0070e4dbff", "to": "FIG-7dcce12c22a6e03b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7dcce12c22a6e03b", "to": "FIG-3bdec3d0fa4ae14f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
